const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/custom_field_definitions/%7Bcustom_field_definition_id%7D/custom_field_lov_entries/bulk_create',
  headers: {'content-type': 'application/json'},
  body: {custom_field_lov_entries: [{label: 'Field-Label-23'}]},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/custom_field_definitions/%7Bcustom_field_definition_id%7D/custom_field_lov_entries/bulk_create"),
    Content = new StringContent("{\"custom_field_lov_entries\":[{\"label\":\"Field-Label-23\"}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
